#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <errno.h>

#include <nuttx/i2c/i2c_master.h>
#include <nuttx/video/ov2640.h>
#include <nuttx/video/imgdata.h>
#include <nuttx/video/imgsensor.h>
#include <nuttx/video/v4l2_cap.h>

#include "esp32s3_cam.h"
#include "esp32s3_i2c.h"

#include "esp32dami.h"

/****************************************************************************
 * Private Function Prototypes — OV2640 imgsensor ops
 ****************************************************************************/

static bool ov2640_is_available(FAR struct imgsensor_s *sensor);
static int ov2640_sensor_init(FAR struct imgsensor_s *sensor);
static int ov2640_sensor_uninit(FAR struct imgsensor_s *sensor);
static FAR const char *ov2640_get_driver_name(FAR struct imgsensor_s *sensor);
static int ov2640_validate_frame(FAR struct imgsensor_s *sensor,
                                 imgsensor_stream_type_t type,
                                 uint8_t nr_datafmts,
                                 FAR imgsensor_format_t *datafmts,
                                 FAR imgsensor_interval_t *interval);
static int ov2640_start_capture(FAR struct imgsensor_s *sensor,
                                imgsensor_stream_type_t type,
                                uint8_t nr_datafmts,
                                FAR imgsensor_format_t *datafmts,
                                FAR imgsensor_interval_t *interval);
static int ov2640_stop_capture(FAR struct imgsensor_s *sensor,
                               imgsensor_stream_type_t type);
static int ov2640_get_frame_interval(FAR struct imgsensor_s *sensor,
                                     imgsensor_stream_type_t type,
                                     FAR imgsensor_interval_t *interval);

/****************************************************************************
 * Private Data — OV2640 sensor ops vtable
 ****************************************************************************/

static const struct imgsensor_ops_s g_ov2640_ops =
{
  .is_available           = ov2640_is_available,
  .init                   = ov2640_sensor_init,
  .uninit                 = ov2640_sensor_uninit,
  .get_driver_name        = ov2640_get_driver_name,
  .validate_frame_setting = ov2640_validate_frame,
  .start_capture          = ov2640_start_capture,
  .stop_capture           = ov2640_stop_capture,
  .get_frame_interval     = ov2640_get_frame_interval,
  .get_supported_value    = NULL,
  .get_value              = NULL,
  .set_value              = NULL,
};

static struct imgsensor_s g_ov2640_sensor =
{
  .ops = &g_ov2640_ops,
};

/****************************************************************************
 * Private Functions — OV2640 imgsensor ops implementation
 ****************************************************************************/

static bool ov2640_is_available(FAR struct imgsensor_s *sensor)
{
  return true;
}

static int ov2640_sensor_init(FAR struct imgsensor_s *sensor)
{
  /* OV2640 is already initialized by ov2640_initialize() in
   * board_camera_initialize(), so nothing to do here.
   */

  return OK;
}

static int ov2640_sensor_uninit(FAR struct imgsensor_s *sensor)
{
  return OK;
}

static FAR const char *ov2640_get_driver_name(FAR struct imgsensor_s *sensor)
{
  return "OV2640";
}

static int ov2640_validate_frame(FAR struct imgsensor_s *sensor,
                                 imgsensor_stream_type_t type,
                                 uint8_t nr_datafmts,
                                 FAR imgsensor_format_t *datafmts,
                                 FAR imgsensor_interval_t *interval)
{
  if (datafmts == NULL || nr_datafmts == 0)
    {
      return -EINVAL;
    }

  /* OV2640 supports RGB565 and JPEG */

  if (datafmts[0].pixelformat != IMGSENSOR_PIX_FMT_RGB565 &&
      datafmts[0].pixelformat != IMGSENSOR_PIX_FMT_JPEG)
    {
      return -EINVAL;
    }

  return OK;
}

static int ov2640_start_capture(FAR struct imgsensor_s *sensor,
                                imgsensor_stream_type_t type,
                                uint8_t nr_datafmts,
                                FAR imgsensor_format_t *datafmts,
                                FAR imgsensor_interval_t *interval)
{
  /* The actual capture is driven by the imgdata interface
   * (esp32s3_cam), not the sensor.  Nothing to do here.
   */

  return OK;
}

static int ov2640_stop_capture(FAR struct imgsensor_s *sensor,
                               imgsensor_stream_type_t type)
{
  return OK;
}

static int ov2640_get_frame_interval(FAR struct imgsensor_s *sensor,
                                     imgsensor_stream_type_t type,
                                     FAR imgsensor_interval_t *interval)
{
  if (interval == NULL)
    {
      return -EINVAL;
    }

  /* Default to 15 fps */

  interval->numerator   = 1;
  interval->denominator = 15;
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int board_camera_initialize(void)
{
  FAR struct i2c_master_s *i2c;
  FAR struct imgdata_s *data;
  FAR struct imgsensor_s *sensor;
  int ret;

  printf("board_camera: start init\n");

  data = esp32s3_cam_initialize();
  if (data == NULL)
    {
      printf("board_camera: cam init failed\n");
      return -ENODEV;
    }

  i2c = esp32s3_i2cbus_initialize(1);
  if (i2c == NULL)
    {
      printf("board_camera: I2C get failed\n");
      return -ENODEV;
    }

  usleep(100000);

  ret = ov2640_initialize(i2c);
  if (ret < 0)
    {
      printf("board_camera: ov2640 failed: %d\n", ret);
      return ret;
    }

  printf("board_camera: registering /dev/video\n");

  sensor = &g_ov2640_sensor;
  ret = capture_register("/dev/video", data, &sensor, 1);
  if (ret < 0)
    {
      printf("board_camera: capture_register failed: %d\n", ret);
      return ret;
    }

  return OK;
}

