108	/****************************************************************************
109	 * Name: camera_prepare()
110	 *
111	 * Description:
112	 *   Allocate frame buffer for camera and queue the allocated buffer
113	 *   into video driver.
114	 ****************************************************************************/
115	
116	static int camera_prepare(int fd, enum v4l2_buf_type type,
117	                          uint32_t buf_mode, uint32_t pixformat,
118	                          uint16_t hsize, uint16_t vsize,
119	                          FAR struct v_buffer **vbuf,
120	                          uint8_t buffernum, int buffersize)
121	{
122	  int ret;
123	  int cnt;
124	  struct v4l2_format fmt =
125	  {
126	    0
127	  };
128	
129	  struct v4l2_requestbuffers req =
130	  {
131	    0
132	  };
133	
134	  struct v4l2_buffer buf =
135	  {
136	    0
137	  };
138	
139	  /* VIDIOC_S_FMT set format */
140	
141	  fmt.type                = type;
142	  fmt.fmt.pix.width       = hsize;
143	  fmt.fmt.pix.height      = vsize;
144	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
145	  fmt.fmt.pix.pixelformat = pixformat;
146	
147	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
148	  if (ret < 0)
149	    {
150	      printf("Failed to VIDIOC_S_FMT: errno = %d\n", errno);
151	      return ret;
152	    }
153	
154	  /* VIDIOC_REQBUFS initiate user pointer I/O */
155	
156	  req.type   = type;
157	  req.memory = V4L2_MEMORY_USERPTR;
158	  req.count  = buffernum;
159	  req.mode   = buf_mode;
160	
161	  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
162	  if (ret < 0)
163	    {
164	      printf("Failed to VIDIOC_REQBUFS: errno = %d\n", errno);
165	      return ret;
166	    }
167	
168	  /* Prepare video memory to store images */
169	
170	  *vbuf = malloc(sizeof(v_buffer_t) * buffernum);
171	  if (!(*vbuf))
172	    {
173	      printf("Out of memory for array of v_buffer_t[%d]\n", buffernum);
174	      return ERROR;
175	    }
176	
177	  for (cnt = 0; cnt < buffernum; cnt++)
178	    {
179	      (*vbuf)[cnt].length = buffersize;
180	
181	      /* Note:
182	       * VIDIOC_QBUF set buffer pointer.
183	       * Buffer pointer must be 32bytes aligned.
184	       */
185	
186	      (*vbuf)[cnt].start = memalign(32, buffersize);
187	      if (!(*vbuf)[cnt].start)
188	        {
189	          printf("Out of memory for image buffer of %d/%d\n",
190	                 cnt, buffernum);
191	
192	          /* Release allocated memory. */
193	
194	          while (cnt--)
195	            {
196	              free((*vbuf)[cnt].start);
197	            }
198	
199	          free(*vbuf);
200	          *vbuf = NULL;
201	          return ERROR;
202	        }
203	    }
204	
205	  /* VIDIOC_QBUF enqueue buffer */
206	
207	  for (cnt = 0; cnt < buffernum; cnt++)
208	    {
209	      memset(&buf, 0, sizeof(v4l2_buffer_t));
210	      buf.type = type;
211	      buf.memory = V4L2_MEMORY_USERPTR;
212	      buf.index = cnt;
213	      buf.m.userptr = (uintptr_t)(*vbuf)[cnt].start;
214	      buf.length = (*vbuf)[cnt].length;
215	
216	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
217	      if (ret)
218	        {
219	          printf("Fail QBUF %d\n", errno);
220	          free_buffer(*vbuf, buffernum);
221	          *vbuf = NULL;
222	          return ERROR;
223	        }
224	    }
225	
226	  /* VIDIOC_STREAMON start stream */
227	
228	  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
229	  if (ret < 0)
230	    {
231	      printf("Failed to VIDIOC_STREAMON: errno = %d\n", errno);
232	      free_buffer(*vbuf, buffernum);
233	      *vbuf = NULL;
234	      return ret;
235	    }
236	
237	  return OK;
238	}
239	
240	/****************************************************************************
241	 * Name: free_buffer()
242	 *
243	 * Description:
244	 *   All free allocated memory of v_buffer.
245	 ****************************************************************************/
246	
247	static void free_buffer(FAR struct v_buffer *buffers, uint8_t bufnum)
248	{
249	  uint8_t cnt;
250	  if (buffers)
251	    {
252	      for (cnt = 0; cnt < bufnum; cnt++)
253	        {
254	          if (buffers[cnt].start)
255	            {
256	              free(buffers[cnt].start);
257	            }
258	        }
259	
260	      free(buffers);
261	    }
262	}
