264	/****************************************************************************
265	 * Name: parse_argument()
266	 *
267	 * Description:
268	 *   Parse and decode commandline arguments.
269	 ****************************************************************************/
270	
271	static int parse_arguments(int argc, FAR char *argv[],
272	                           FAR int *capture_num,
273	                           FAR enum v4l2_buf_type *type)
274	{
275	  if (argc == 1)
276	    {
277	      *capture_num = DEFAULT_CAPTURE_NUM;
278	      *type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
279	    }
280	  else if (argc == 2)
281	    {
282	      if (strncmp(argv[1], "-jpg", 5) == 0)
283	        {
284	          *capture_num = DEFAULT_CAPTURE_NUM;
285	          *type = V4L2_BUF_TYPE_STILL_CAPTURE;
286	        }
287	      else
288	        {
289	          *capture_num = atoi(argv[1]);
290	          if (*capture_num < 0 || *capture_num > MAX_CAPTURE_NUM)
291	            {
292	              printf("Invalid capture num(%d). must be >=0 and <=%d\n",
293	                    *capture_num, MAX_CAPTURE_NUM);
294	              return ERROR;
295	            }
296	
297	          *type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
298	        }
299	    }
300	  else if (argc == 3)
301	    {
302	      if (strncmp(argv[1], "-jpg", 5) == 0)
303	        {
304	          *capture_num = atoi(argv[2]);
305	          if (*capture_num < 0 || *capture_num > MAX_CAPTURE_NUM)
306	            {
307	              printf("Invalid capture num(%d). must be >=0 and <=%d\n",
308	                    *capture_num, MAX_CAPTURE_NUM);
309	              return ERROR;
310	            }
311	
312	          *type = V4L2_BUF_TYPE_STILL_CAPTURE;
313	        }
314	      else
315	        {
316	          printf("Invalid argument 1 : %s\n", argv[1]);
317	          return ERROR;
318	        }
319	    }
320	  else
321	    {
322	      printf("Too many arguments\n");
323	      return ERROR;
324	    }
325	
326	  return OK;
327	}
