329	/****************************************************************************
330	 * Name: get_camimage()
331	 *
332	 * Description:
333	 *   DQBUF camera frame buffer from video driver with taken picture data.
334	 ****************************************************************************/
335	
336	static int get_camimage(int fd, FAR struct v4l2_buffer *v4l2_buf,
337	                        enum v4l2_buf_type buf_type)
338	{
339	  int ret;
340	
341	  /* VIDIOC_DQBUF acquires captured data. */
342	
343	  memset(v4l2_buf, 0, sizeof(v4l2_buffer_t));
344	  v4l2_buf->type = buf_type;
345	  v4l2_buf->memory = V4L2_MEMORY_USERPTR;
346	
347	  ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)v4l2_buf);
348	  if (ret)
349	    {
350	      printf("Fail DQBUF %d\n", errno);
351	      return ERROR;
352	    }
353	
354	  return OK;
355	}
