357	/****************************************************************************
358	 * Name: release_camimage()
359	 *
360	 * Description:
361	 *   Re-QBUF to set used frame buffer into video driver.
362	 ****************************************************************************/
363	
364	static int release_camimage(int fd, FAR struct v4l2_buffer *v4l2_buf)
365	{
366	  int ret;
367	
368	  /* VIDIOC_QBUF sets buffer pointer into video driver again. */
369	
370	  ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)v4l2_buf);
371	  if (ret)
372	    {
373	      printf("Fail QBUF %d\n", errno);
374	      return ERROR;
375	    }
376	
377	  return OK;
378	}
