380	/****************************************************************************
381	 * Name: start_stillcapture()
382	 *
383	 * Description:
384	 *   Start STILL capture stream by TAKEPICT_START if buf_type is
385	 *   STILL_CAPTURE.
386	 ****************************************************************************/
387	
388	static int start_stillcapture(int v_fd, enum v4l2_buf_type capture_type)
389	{
390	  int ret;
391	
392	  if (capture_type == V4L2_BUF_TYPE_STILL_CAPTURE)
393	    {
394	      ret = ioctl(v_fd, VIDIOC_TAKEPICT_START, 0);
395	      if (ret < 0)
396	        {
397	          printf("Failed to start taking picture\n");
398	          return ERROR;
399	        }
400	    }
401	
402	  return OK;
403	}
