405	/****************************************************************************
406	 * Name: stop_stillcapture()
407	 *
408	 * Description:
409	 *   Stop STILL capture stream by TAKEPICT_STOP if buf_type is STILL_CAPTURE.
410	 ****************************************************************************/
411	
412	static int stop_stillcapture(int v_fd, enum v4l2_buf_type capture_type)
413	{
414	  int ret;
415	
416	  if (capture_type == V4L2_BUF_TYPE_STILL_CAPTURE)
417	    {
418	      ret = ioctl(v_fd, VIDIOC_TAKEPICT_STOP, false);
419	      if (ret < 0)
420	        {
421	          printf("Failed to stop taking picture\n");
422	          return ERROR;
423	        }
424	    }
425	
426	  return OK;
427	}
