445	/****************************************************************************
446	 * Public Functions
447	 ****************************************************************************/
448	
449	/****************************************************************************
450	 * Name: main()
451	 *
452	 * Description:
453	 *   main routine of this example.
454	 ****************************************************************************/
455	
456	int main(int argc, FAR char *argv[])
457	{
458	  int ret;
459	  int v_fd;
460	  int capture_num = DEFAULT_CAPTURE_NUM;
461	  enum v4l2_buf_type capture_type = V4L2_BUF_TYPE_STILL_CAPTURE;
462	  struct v4l2_buffer v4l2_buf;
463	  FAR const char *save_dir;
464	  FAR const char *sensor;
465	  uint16_t w;
466	  uint16_t h;
467	  int is_eternal;
468	  int app_state;
469	
470	  struct timeval start;
471	  struct timeval now;
472	  struct timeval delta;
473	  struct timeval wait;
474	
475	  FAR struct v_buffer *buffers_video = NULL;
476	  FAR struct v_buffer *buffers_still = NULL;
477	
478	  /* =====  Parse and Check arguments  ===== */
479	
480	  ret = parse_arguments(argc, argv, &capture_num, &capture_type);
481	  if (ret != OK)
482	    {
483	      printf("usage: %s ([-jpg]) ([capture num])\n", argv[0]);
484	      return ERROR;
485	    }
486	
487	  /* =====  Initialization Code  ===== */
488	
489	  /* Initialize NX graphics subsystem to use LCD */
490	
491	#ifdef CONFIG_EXAMPLES_CAMERA_OUTPUT_LCD
492	  ret = nximage_initialize();
493	  if (ret < 0)
494	    {
495	      printf("camera_main: Failed to get NX handle: %d\n", errno);
496	      return ERROR;
497	    }
498	#endif
499	
500	  /* Select storage to save image files */
501	
502	  save_dir = futil_initialize();
503	
504	  /* Initialize video driver to create a device file */
505	
506	  ret = capture_initialize(CAMERA_DEV_PATH);
507	  if (ret != 0)
508	    {
509	      printf("ERROR: Failed to initialize video: errno = %d\n", errno);
510	      goto exit_without_cleaning_videodriver;
511	    }
512	
513	  /* Open the device file. */
514	
515	  v_fd = open(CAMERA_DEV_PATH, 0);
516	  if (v_fd < 0)
517	    {
518	      printf("ERROR: Failed to open video.errno = %d\n", errno);
519	      ret = ERROR;
520	      goto exit_without_cleaning_buffer;
521	    }
522	
523	  /* Prepare for STILL_CAPTURE stream.
524	   *
525	   * The video buffer mode is V4L2_BUF_MODE_FIFO mode.
526	   * In this FIFO mode, if all VIDIOC_QBUFed frame buffers are captured image
527	   * and no additional frame buffers are VIDIOC_QBUFed, the capture stops and
528	   * waits for new VIDIOC_QBUFed frame buffer.
529	   * And when new VIDIOC_QBUF is executed, the capturing is resumed.
530	   *
531	   * Allocate frame buffers for JPEG size (512KB).
532	   * Set FULLHD size in ISX012 case, QUADVGA size in ISX019 case or other
533	   * image sensors,
534	   * Number of frame buffers is defined as STILL_BUFNUM(1).
535	   * And all allocated memorys are VIDIOC_QBUFed.
536	   */
537	
538	  if (capture_num != 0)
539	    {
540	      /* Determine image size from connected image sensor name,
541	       * because video driver does not support VIDIOC_ENUM_FRAMESIZES
542	       * for now.
543	       */
544	
545	      sensor = get_imgsensor_name(v_fd);
546	      if (strncmp(sensor, "ISX012", strlen("ISX012")) == 0)
547	        {
548	          w = VIDEO_HSIZE_FULLHD;
549	          h = VIDEO_VSIZE_FULLHD;
550	        }
551	      else if (strncmp(sensor, "ISX019", strlen("ISX019")) == 0)
552	        {
553	          w = VIDEO_HSIZE_QUADVGA;
554	          h = VIDEO_VSIZE_QUADVGA;
555	        }
556	      else
557	        {
558	          w = VIDEO_HSIZE_QUADVGA;
559	          h = VIDEO_VSIZE_QUADVGA;
560	        }
561	
562	      ret = camera_prepare(v_fd, V4L2_BUF_TYPE_STILL_CAPTURE,
563	                           V4L2_BUF_MODE_FIFO, V4L2_PIX_FMT_JPEG,
564	                           w, h,
565	                           &buffers_still, STILL_BUFNUM, IMAGE_JPG_SIZE);
566	      if (ret != OK)
567	        {
568	          goto exit_this_app;
569	        }
570	    }
571	
572	  /* Prepare for VIDEO_CAPTURE stream.
573	   *
574	   * The video buffer mode is V4L2_BUF_MODE_RING mode.
575	   * In this RING mode, if all VIDIOC_QBUFed frame buffers are captured image
576	   * and no additional frame buffers are VIDIOC_QBUFed, the capture continues
577	   * as the oldest image in the V4L2_BUF_QBUFed frame buffer is reused in
578	   * order from the captured frame buffer and a new camera image is
579	   * recaptured.
580	   *
581	   * Allocate freame buffers for QVGA RGB565 size (320x240x2=150KB).
582	   * Number of frame buffers is defined as VIDEO_BUFNUM(3).
583	   * And all allocated memorys are VIDIOC_QBUFed.
584	   */
585	
586	  ret = camera_prepare(v_fd, V4L2_BUF_TYPE_VIDEO_CAPTURE,
587	                       V4L2_BUF_MODE_RING, V4L2_PIX_FMT_RGB565,
588	                       VIDEO_HSIZE_QVGA, VIDEO_VSIZE_QVGA,
589	                       &buffers_video, VIDEO_BUFNUM, IMAGE_RGB_SIZE);
590	  if (ret != OK)
591	    {
592	      goto exit_this_app;
593	    }
594	
595	  /* This application has 3 states.
596	   *
597	   * APP_STATE_BEFORE_CAPTURE:
598	   *    This state waits 5 seconds (defined as START_CAPTURE_TIME)
599	   *    with displaying preview (VIDEO_CAPTURE stream image) on LCD.
600	   *    After 5 seconds, state will be changed to APP_STATE_UNDER_CAPTURE.
601	   *
602	   * APP_STATE_UNDER_CAPTURE:
603	   *    This state will start taking picture and store the image into files.
604	   *    Number of taking pictures is set capture_num valiable.
605	   *    It can be changed by command line argument.
606	   *    After finishing taking pictures, the state will be changed to
607	   *    APP_STATE_AFTER_CAPTURE.
608	   *
609	   * APP_STATE_AFTER_CAPTURE:
610	   *    This state waits 10 seconds (defined as KEEP_VIDEO_TIME)
611	   *    with displaying preview (VIDEO_CAPTURE stream image) on LCD.
612	   *    After 10 seconds, this application will be finished.
613	   *
614	   * Notice:
615	   *    If capture_num is set '0', state will stay APP_STATE_BEFORE_CAPTURE.
616	   */
617	
618	  app_state = APP_STATE_BEFORE_CAPTURE;
619	
620	  /* Show this application behavior. */
621	
622	  if (capture_num == 0)
623	    {
624	      is_eternal = 1;
625	      printf("Start video this mode is eternal."
626	             " (Non stop, non save files.)\n");
627	#ifndef CONFIG_EXAMPLES_CAMERA_OUTPUT_LCD
628	      printf("This mode should be run with LCD display\n");
629	#endif
630	    }
631	  else
632	    {
633	      is_eternal = 0;
634	      wait.tv_sec = START_CAPTURE_TIME;
635	      wait.tv_usec = 0;
636	      printf("Take %d pictures as %s file in %s after %d seconds.\n",
637	             capture_num,
638	             capture_type == V4L2_BUF_TYPE_STILL_CAPTURE ? "JPEG" : "RGB",
639	             save_dir, START_CAPTURE_TIME);
640	      printf(" After finishing taking pictures,"
641	             " this app will be finished after %d seconds.\n",
642	              KEEP_VIDEO_TIME);
643	    }
644	
645	  gettimeofday(&start, NULL);
646	
647	  /* =====  Main Loop  ===== */
648	
649	  while (1)
650	    {
651	      switch (app_state)
652	        {
653	          /* BEFORE_CAPTURE and AFTER_CAPTURE is waiting for expiring the
654	           * time.
655	           * In the meantime, Capturing VIDEO image to show pre-view on LCD.
656	           */
657	
658	          case APP_STATE_BEFORE_CAPTURE:
659	          case APP_STATE_AFTER_CAPTURE:
660	            ret = get_camimage(v_fd, &v4l2_buf, V4L2_BUF_TYPE_VIDEO_CAPTURE);
661	            if (ret != OK)
662	              {
663	                goto exit_this_app;
664	              }
665	
666	#ifdef CONFIG_EXAMPLES_CAMERA_OUTPUT_LCD
667	            nximage_draw((FAR void *)v4l2_buf.m.userptr,
668	                         VIDEO_HSIZE_QVGA, VIDEO_VSIZE_QVGA);
669	#endif
670	
671	            ret = release_camimage(v_fd, &v4l2_buf);
672	            if (ret != OK)
673	              {
674	                goto exit_this_app;
675	              }
676	
677	            if (!is_eternal)
678	              {
679	                gettimeofday(&now, NULL);
680	                timersub(&now, &start, &delta);
681	                if (timercmp(&delta, &wait, > /* For checkpatch */))
682	                  {
683	                    printf("Expire time is pasted. GoTo next state.\n");
684	                    if (app_state == APP_STATE_BEFORE_CAPTURE)
685	                      {
686	                        app_state = APP_STATE_UNDER_CAPTURE;
687	                      }
688	                    else
689	                      {
690	                        ret = OK;
691	                        goto exit_this_app;
692	                      }
693	                  }
694	              }
695	
696	            break; /* Finish APP_STATE_BEFORE_CAPTURE or APP_STATE_AFTER_CAPTURE */
697	
698	          /* UNDER_CAPTURE is taking pictures until number of capture_num
699	           * value.
700	           * This state stays until finishing all pictures.
701	           */
702	
703	          case APP_STATE_UNDER_CAPTURE:
704	            printf("Start capturing...\n");
705	            ret = start_stillcapture(v_fd, capture_type);
706	            if (ret != OK)
707	              {
708	                goto exit_this_app;
709	              }
710	
711	            while (capture_num)
712	              {
713	                ret = get_camimage(v_fd, &v4l2_buf, capture_type);
714	                if (ret != OK)
715	                  {
716	                    goto exit_this_app;
717	                  }
718	
719	                futil_writeimage(
720	                  (FAR uint8_t *)v4l2_buf.m.userptr,
721	                  (size_t)v4l2_buf.bytesused,
722	                  capture_type == V4L2_BUF_TYPE_VIDEO_CAPTURE ?
723	                  "RGB" : "JPG");
724	
725	                ret = release_camimage(v_fd, &v4l2_buf);
726	                if (ret != OK)
727	                  {
728	                    goto exit_this_app;
729	                  }
730	
731	                capture_num--;
732	              }
733	
734	            ret = stop_stillcapture(v_fd, capture_type);
735	            if (ret != OK)
736	              {
737	                goto exit_this_app;
738	              }
739	
740	            app_state = APP_STATE_AFTER_CAPTURE;
741	            wait.tv_sec = KEEP_VIDEO_TIME;
742	            wait.tv_usec = 0;
743	            gettimeofday(&start, NULL);
744	            printf("Finished capturing...\n");
745	            break; /* Finish APP_STATE_UNDER_CAPTURE */
746	
747	          default:
748	            printf("Unknown error is occurred.. state=%d\n", app_state);
749	            goto exit_this_app;
750	            break;
751	        }
752	    }
753	
754	exit_this_app:
755	
756	  /* Close video device file makes dequeue all buffers */
757	
758	  close(v_fd);
759	
760	  free_buffer(buffers_video, VIDEO_BUFNUM);
761	  free_buffer(buffers_still, STILL_BUFNUM);
762	
763	exit_without_cleaning_buffer:
764	  capture_uninitialize(CAMERA_DEV_PATH);
765	
766	exit_without_cleaning_videodriver:
767	#ifdef CONFIG_EXAMPLES_CAMERA_OUTPUT_LCD
768	  nximage_finalize();
769	#endif
770	  return ret;
771	}
