106	/****************************************************************************
107	 * Name: arg_string
108	 ****************************************************************************/
109	
110	static int arg_string(FAR char **arg, FAR char **value)
111	{
112	  FAR char *ptr = *arg;
113	
114	  if (ptr[2] == '\0')
115	    {
116	      *value = arg[1];
117	      return 2;
118	    }
119	  else
120	    {
121	      *value = &ptr[2];
122	      return 1;
123	    }
124	}
