126	/****************************************************************************
127	 * Name: arg_decimal
128	 ****************************************************************************/
129	
130	static int arg_decimal(FAR char **arg, FAR long *value)
131	{
132	  FAR char *string;
133	  int ret;
134	
135	  ret = arg_string(arg, &string);
136	  *value = strtol(string, NULL, 10);
137	  return ret;
138	}
