140	/****************************************************************************
141	 * Name: parse_args
142	 ****************************************************************************/
143	
144	static void parse_args(int argc, FAR char **argv)
145	{
146	  FAR char *ptr;
147	  FAR char *str;
148	  long value;
149	  int index;
150	  int nargs;
151	
152	  g_capexample.nloops = CONFIG_EXAMPLES_CAPTURE_NSAMPLES;
153	  g_capexample.delay  = CONFIG_EXAMPLES_CAPTURE_DELAY;
154	  g_capexample.signo  = 1;
155	
156	  for (index = 1; index < argc; )
157	    {
158	      ptr = argv[index];
159	      if (ptr[0] != '-')
160	        {
161	          printf("Invalid options format: %s\n", ptr);
162	          exit(0);
163	        }
164	
165	      switch (ptr[1])
166	        {
167	          case 'n':
168	            nargs = arg_decimal(&argv[index], &value);
169	            if (value < 0 || value > INT_MAX)
170	              {
171	                printf("Sample count out of range: %ld\n", value);
172	                exit(1);
173	              }
174	
175	            g_capexample.nloops = (unsigned int)value;
176	            index += nargs;
177	            break;
178	
179	          case 'p':
180	            nargs = arg_string(&argv[index], &str);
181	            cap_devpath(str);
182	            index += nargs;
183	            break;
184	
185	          case 't':
186	            nargs = arg_decimal(&argv[index], &value);
187	            if (value < 0 || value > INT_MAX)
188	              {
189	                printf("Sample delay out of range: %ld\n", value);
190	                exit(1);
191	              }
192	
193	            g_capexample.delay = (unsigned int)value;
194	            index += nargs;
195	            break;
196	
197	#ifdef CONFIG_CAPTURE_NOTIFY
198	          case 'w':
199	            nargs = arg_decimal(&argv[index], &value);
200	            if (value < MIN_SIGNO || value > MAX_SIGNO)
201	              {
202	                printf("Wait signo out of range: %ld\n", value);
203	                exit(1);
204	              }
205	
206	            g_capexample.signo = (int)value;
207	            index += nargs;
208	            break;
209	#endif
210	
211	          case 'h':
212	            cap_help();
213	            exit(EXIT_SUCCESS);
214	
215	          default:
216	            printf("Unsupported option: %s\n", ptr);
217	            cap_help();
218	            exit(EXIT_FAILURE);
219	        }
220	    }
221	}
