227	/****************************************************************************
228	 * Name: cap_main
229	 ****************************************************************************/
230	
231	int main(int argc, FAR char *argv[])
232	{
233	  int8_t dutycycle;
234	  int32_t frequence;
235	  int32_t edges;
236	  int fd;
237	  int exitval = EXIT_SUCCESS;
238	  int ret;
239	  int nloops;
240	#ifdef CONFIG_CAPTURE_NOTIFY
241	  struct cap_notify_s notify;
242	  struct timespec ts;
243	  sigset_t set;
244	#endif
245	
246	  /* Set the default values */
247	
248	  cap_devpath(CONFIG_EXAMPLES_CAPTURE_DEVPATH);
249	
250	  /* Parse command line arguments */
251	
252	  parse_args(argc, argv);
253	
254	  /* Open the capture device for reading */
255	
256	  printf("cap_main: Hardware initialized. Opening the capture device: %s\n",
257	         g_capexample.devpath);
258	
259	  fd = open(g_capexample.devpath, O_RDONLY);
260	  if (fd < 0)
261	    {
262	      printf("cap_main: open %s failed: %d\n", g_capexample.devpath, errno);
263	      exitval = EXIT_FAILURE;
264	      goto errout;
265	    }
266	
267	#ifdef CONFIG_CAPTURE_NOTIFY
268	  notify.chan = 0;
269	  notify.type = CAP_TYPE_BOTH;
270	
271	  notify.event.sigev_notify = SIGEV_SIGNAL;
272	  notify.event.sigev_signo  = g_capexample.signo;
273	
274	  ret = ioctl(fd, CAPIOC_REGISTER, (unsigned long)&notify);
275	  if (ret < 0)
276	    {
277	      printf("cap_main: ioctl(GPIOC_REGISTER) failed: %d\n", errno);
278	      exitval = EXIT_FAILURE;
279	      goto errout_with_dev;
280	    }
281	
282	  /* Wait up to 5 seconds for the signal */
283	
284	  sigemptyset(&set);
285	  sigaddset(&set, g_capexample.signo);
286	
287	  ts.tv_sec  = 5;
288	  ts.tv_nsec = 0;
289	
290	  ret = sigtimedwait(&set, NULL, &ts);
291	  ioctl(fd, CAPIOC_UNREGISTER, notify.chan);
292	  if (ret < 0)
293	    {
294	      int errcode = errno;
295	      if (errcode == EAGAIN)
296	        {
297	          printf("cpu_main: Five second timeout with no signal\n");
298	          exitval = EXIT_FAILURE;
299	          goto errout_with_dev;
300	        }
301	      else
302	        {
303	          printf("cpu_main: ERROR: Failed to wait signal %d "
304	                 "from %s: %d\n", g_capexample.signo, g_capexample.devpath,
305	                 errcode);
306	          exitval = EXIT_FAILURE;
307	          goto errout_with_dev;
308	        }
309	    }
310	  else
311	    {
312	      printf("cap_main: Received signal %d from %s\n",
313	             g_capexample.signo, g_capexample.devpath);
314	    }
315	#endif
316	
317	  /* Now loop the appropriate number of times, displaying the collected
318	   * encoder samples.
319	   */
320	
321	  printf("cap_main: Number of samples: %u\n", g_capexample.nloops);
322	  for (nloops = 0;
323	       !g_capexample.nloops || nloops < g_capexample.nloops;
324	       nloops++)
325	    {
326	      /* Flush any output before the loop entered or from the previous pass
327	       * through the loop.
328	       */
329	
330	      fflush(stdout);
331	
332	      /* Get the dutycycle data using the ioctl */
333	
334	      ret = ioctl(fd, CAPIOC_DUTYCYCLE,
335	                  (unsigned long)((uintptr_t)&dutycycle));
336	      if (ret < 0)
337	        {
338	          printf("cap_main: ioctl(CAPIOC_DUTYCYCLE) failed: %d\n", errno);
339	          exitval = EXIT_FAILURE;
340	          goto errout_with_dev;
341	        }
342	
343	      /* Print the sample data on successful return */
344	
345	      else
346	        {
347	          printf("pwm duty cycle: %d %% \n", dutycycle);
348	        }
349	
350	      /* Get the frequence data using the ioctl */
351	
352	      ret = ioctl(fd, CAPIOC_FREQUENCE,
353	                  (unsigned long)((uintptr_t)&frequence));
354	      if (ret < 0)
355	        {
356	          printf("cap_main: ioctl(CAPIOC_FREQUENCE) failed: %d\n", errno);
357	          exitval = EXIT_FAILURE;
358	          goto errout_with_dev;
359	        }
360	
361	      /* Print the sample data on successful return */
362	
363	      else
364	        {
365	          printf("pwm frequence: %"PRId32" Hz \n", frequence);
366	        }
367	
368	      /* Get the edges data using the ioctl */
369	
370	      ret = ioctl(fd, CAPIOC_EDGES,
371	                  (unsigned long)((uintptr_t)&edges));
372	      if (ret < 0)
373	        {
374	          printf("cap_main: ioctl(CAPIOC_EDGES) failed: %d\n", errno);
375	          exitval = EXIT_FAILURE;
376	          goto errout_with_dev;
377	        }
378	
379	      /* Print the sample data on successful return */
380	
381	      else
382	        {
383	          printf("pwm edges counting: %"PRId32" \n", edges);
384	        }
385	
386	      /* Delay a little bit */
387	
388	      usleep(g_capexample.delay * 1000);
389	    }
390	
391	errout_with_dev:
392	  close(fd);
393	
394	errout:
395	  printf("Terminating!\n");
396	  fflush(stdout);
397	  return exitval;
398	}
