98	static void sync_area(FAR struct fb_state_s *state)
99	{
100	  if (state->fbmem2 == NULL)
101	    {
102	      return;
103	    }
104	
105	  if (state->act_fbmem == state->fbmem)
106	    {
107	      memcpy(state->fbmem, state->fbmem2,
108	             state->vinfo.yres * state->pinfo.stride);
109	    }
110	  else
111	    {
112	      memcpy(state->fbmem2, state->fbmem,
113	             state->vinfo.yres * state->pinfo.stride);
114	    }
115	}
