118	 * pan_display
119	 ****************************************************************************/
120	
121	static void pan_display(FAR struct fb_state_s *state)
122	{
123	  struct pollfd pfd;
124	  int ret;
125	  pfd.fd = state->fd;
126	  pfd.events = POLLOUT;
127	
128	  ret = poll(&pfd, 1, 0);
129	
130	  if (ret > 0)
131	    {
132	      if (state->fbmem2 == NULL)
133	        {
134	          return;
135	        }
136	
137	      if (state->act_fbmem == state->fbmem)
138	        {
139	          state->pinfo.yoffset = 0;
140	        }
141	      else
142	        {
143	          state->pinfo.yoffset = state->mem2_yoffset;
144	        }
145	
146	      ioctl(state->fd, FBIOPAN_DISPLAY,
147	            (unsigned long)(uintptr_t)&state->pinfo);
148	
149	      state->act_fbmem = state->act_fbmem == state->fbmem ?
150	                         state->fbmem2 : state->fbmem;
151	    }
152	}
