157	
158	static int fbdev_get_pinfo(int fd, FAR struct fb_planeinfo_s *pinfo)
159	{
160	  if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)pinfo)) < 0)
161	    {
162	      int errcode = errno;
163	      fprintf(stderr, "ERROR: ioctl(FBIOGET_PLANEINFO) failed: %d\n",
164	              errcode);
165	      return EXIT_FAILURE;
166	    }
167	
168	  printf("PlaneInfo (plane %d):\n", pinfo->display);
169	  printf("    fbmem: %p\n", pinfo->fbmem);
170	  printf("    fblen: %zu\n", pinfo->fblen);
171	  printf("   stride: %u\n", pinfo->stride);
172	  printf("  display: %u\n", pinfo->display);
173	  printf("      bpp: %u\n", pinfo->bpp);
174	
175	  /* Only these pixel depths are supported.  viinfo.fmt is ignored, only
176	   * certain color formats are supported.
177	   */
178	
179	  if (pinfo->bpp != 32 && pinfo->bpp != 24 &&
180	      pinfo->bpp != 16 && pinfo->bpp != 8 &&
181	      pinfo->bpp != 1)
182	    {
183	      fprintf(stderr, "ERROR: bpp=%u not supported\n", pinfo->bpp);
184	      return EXIT_FAILURE;
185	    }
186	
187	  return 0;
188	}
