513	 ****************************************************************************/
514	
515	int main(int argc, FAR char *argv[])
516	{
517	  FAR const char *fbdev = g_default_fbdev;
518	  struct fb_state_s state;
519	  struct fb_area_s area;
520	  int nsteps;
521	  int xstep;
522	  int ystep;
523	  int width;
524	  int height;
525	  int color;
526	  int x;
527	  int y;
528	  int ret;
529	
530	  /* There is a single required argument:  The path to the framebuffer
531	   * driver.
532	   */
533	
534	  if (argc == 2)
535	    {
536	      fbdev = argv[1];
537	    }
538	  else if (argc != 1)
539	    {
540	      fprintf(stderr, "ERROR: Single argument required\n");
541	      fprintf(stderr, "USAGE: %s [<fb-driver-path>]\n", argv[0]);
542	      return EXIT_FAILURE;
543	    }
544	
545	  /* Open the framebuffer driver */
546	
547	  state.fd = open(fbdev, O_RDWR);
548	  if (state.fd < 0)
549	    {
550	      int errcode = errno;
551	      fprintf(stderr, "ERROR: Failed to open %s: %d\n", fbdev, errcode);
552	      return EXIT_FAILURE;
553	    }
554	
555	  /* Get the characteristics of the framebuffer */
556	
557	  ret = ioctl(state.fd, FBIOGET_VIDEOINFO,
558	              (unsigned long)((uintptr_t)&state.vinfo));
559	  if (ret < 0)
560	    {
561	      int errcode = errno;
562	      fprintf(stderr, "ERROR: ioctl(FBIOGET_VIDEOINFO) failed: %d\n",
563	              errcode);
564	      close(state.fd);
565	      return EXIT_FAILURE;
566	    }
567	
568	  printf("VideoInfo:\n");
569	  printf("      fmt: %u\n", state.vinfo.fmt);
570	  printf("     xres: %u\n", state.vinfo.xres);
571	  printf("     yres: %u\n", state.vinfo.yres);
572	  printf("  nplanes: %u\n", state.vinfo.nplanes);
573	
574	#ifdef CONFIG_FB_OVERLAY
575	  printf("noverlays: %u\n", state.vinfo.noverlays);
576	
577	  /* Select the first overlay, which should be the composed framebuffer */
578	
579	  ret = ioctl(state.fd, FBIO_SELECT_OVERLAY, 0);
580	  if (ret < 0)
581	    {
582	      int errcode = errno;
583	      fprintf(stderr, "ERROR: ioctl(FBIO_SELECT_OVERLAY) failed: %d\n",
584	              errcode);
585	      close(state.fd);
586	      return EXIT_FAILURE;
587	    }
588	
589	  /* Get the first overlay information */
590	
591	  state.oinfo.overlay = 0;
592	  ret = ioctl(state.fd, FBIOGET_OVERLAYINFO,
593	                        (unsigned long)((uintptr_t)&state.oinfo));
594	  if (ret < 0)
595	    {
596	      int errcode = errno;
597	      fprintf(stderr, "ERROR: ioctl(FBIOGET_OVERLAYINFO) failed: %d\n",
598	              errcode);
599	      close(state.fd);
600	      return EXIT_FAILURE;
601	    }
602	
603	  printf("OverlayInfo (overlay 0):\n");
604	  printf("    fbmem: %p\n", state.oinfo.fbmem);
605	  printf("    fblen: %zu\n", state.oinfo.fblen);
606	  printf("   stride: %u\n", state.oinfo.stride);
607	  printf("  overlay: %u\n", state.oinfo.overlay);
608	  printf("      bpp: %u\n", state.oinfo.bpp);
609	  printf("    blank: %u\n", state.oinfo.blank);
610	  printf("chromakey: 0x%08" PRIx32 "\n", state.oinfo.chromakey);
611	  printf("    color: 0x%08" PRIx32 "\n", state.oinfo.color);
612	  printf("   transp: 0x%02x\n", state.oinfo.transp.transp);
613	  printf("     mode: %u\n", state.oinfo.transp.transp_mode);
614	  printf("     area: (%u,%u) => (%u,%u)\n",
615	                      state.oinfo.sarea.x, state.oinfo.sarea.y,
616	                      state.oinfo.sarea.w, state.oinfo.sarea.h);
617	  printf("     accl: %" PRIu32 "\n", state.oinfo.accl);
618	
619	  /* select default framebuffer layer */
620	
621	  ret = ioctl(state.fd, FBIO_SELECT_OVERLAY, FB_NO_OVERLAY);
622	  if (ret < 0)
623	    {
624	      int errcode = errno;
625	      fprintf(stderr, "ERROR: ioctl(FBIO_SELECT_OVERLAY) failed: %d\n",
626	              errcode);
627	      close(state.fd);
628	      return EXIT_FAILURE;
629	    }
630	
631	#endif
632	
633	  if ((ret = fbdev_get_pinfo(state.fd, &state.pinfo)) < 0)
634	    {
635	      close(state.fd);
636	      return EXIT_FAILURE;
637	    }
638	
639	  /* mmap() the framebuffer.
640	   *
641	   * NOTE: In the FLAT build the frame buffer address returned by the
642	   * FBIOGET_PLANEINFO IOCTL command will be the same as the framebuffer
643	   * address.  mmap(), however, is the preferred way to get the framebuffer
644	   * address because in the KERNEL build, it will perform the necessary
645	   * address mapping to make the memory accessible to the application.
646	   */
647	
648	  state.fbmem = mmap(NULL, state.pinfo.fblen, PROT_READ | PROT_WRITE,
649	                     MAP_SHARED | MAP_FILE, state.fd, 0);
650	  if (state.fbmem == MAP_FAILED)
651	    {
652	      int errcode = errno;
653	      fprintf(stderr, "ERROR: ioctl(FBIOGET_PLANEINFO) failed: %d\n",
654	              errcode);
655	      close(state.fd);
656	      return EXIT_FAILURE;
657	    }
658	
659	  printf("Mapped FB: %p\n", state.fbmem);
660	
661	  /* double buffer mode */
662	
663	  if (state.pinfo.yres_virtual == (state.vinfo.yres * 2))
664	    {
665	      if ((ret = fb_init_mem2(&state)) < 0)
666	        {
667	          munmap(state.fbmem, state.pinfo.fblen);
668	          close(state.fd);
669	          return ret;
670	        }
671	    }
672	
673	  /* Draw some rectangles */
674	
675	  state.act_fbmem = state.fbmem;
676	  nsteps = 2 * (NCOLORS - 1) + 1;
677	  xstep  = state.vinfo.xres / nsteps;
678	  ystep  = state.vinfo.yres / nsteps;
679	  width  = state.vinfo.xres;
680	  height = state.vinfo.yres;
681	
682	  for (x = 0, y = 0, color = 0;
683	       color < NCOLORS;
684	       x += xstep, y += ystep, color++)
685	    {
686	      area.x = x;
687	      area.y = y;
688	      area.w = width;
689	      area.h = height;
690	
691	      printf("%2d: (%3d,%3d) (%3d,%3d)\n",
692	             color, area.x, area.y, area.w, area.h);
693	
694	      draw_rect(&state, &area, color);
695	      usleep(500 * 1000);
696	
697	      width  -= (2 * xstep);
698	      height -= (2 * ystep);
699	
700	      /* double buffer mode */
701	
702	      if (state.pinfo.yres_virtual == (state.vinfo.yres * 2))
703	        {
704	          sync_area(&state);
705	        }
706	    }
707	
708	  printf("FB test finished\n");
709	  ret = EXIT_SUCCESS;
710	
711	  munmap(state.fbmem, state.pinfo.fblen);
712	  munmap(state.fbmem2, state.pinfo.fblen);
713	  close(state.fd);
714	  return ret;
715	}
