/****************************************************************************
 * Private Data — camera display task
 ****************************************************************************/

/* Camera capture resolution (QVGA) */

#define CAM_WIDTH   320
#define CAM_HEIGHT  240

/* LCD resolution (ST7789 portrait 240x240) */

#define LCD_WIDTH   240
#define LCD_HEIGHT  240

#define CAMVIEW_BUFNUM  3

struct camview_buffer
{
  FAR uint32_t *start;
  uint32_t length;
};

/****************************************************************************
 * Name: camview_task
 *
 * Description:
 *   Background task that captures camera frames and displays them on the
 *   LCD framebuffer.  Reads RGB565 frames from /dev/video at QVGA
 *   resolution, copies the center 240x240 region to /dev/fb0.
 *
 ****************************************************************************/

static int camview_task(int argc, FAR char *argv[])
{
  int vfd;
  int ffd;
  int ret;
  int cnt;
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  FAR uint8_t *fbmem;
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer vbuf;
  struct camview_buffer bufs[CAMVIEW_BUFNUM];

  /* Give camera hardware a moment to stabilize */

  usleep(500000);

  /* Open framebuffer */

  ffd = open("/dev/fb0", O_RDWR);
  if (ffd < 0)
    {
      printf("camview: open /dev/fb0 failed: %d\n", errno);
      return -errno;
    }

  ret = ioctl(ffd, FBIOGET_VIDEOINFO, (unsigned long)(uintptr_t)&vinfo);
  if (ret < 0)
    {
      printf("camview: FBIOGET_VIDEOINFO failed: %d\n", errno);
      close(ffd);
      return -errno;
    }

  ret = ioctl(ffd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo);
  if (ret < 0)
    {
      printf("camview: FBIOGET_PLANEINFO failed: %d\n", errno);
      close(ffd);
      return -errno;
    }

  fbmem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
               MAP_SHARED | MAP_FILE, ffd, 0);
  if (fbmem == MAP_FAILED)
    {
      printf("camview: mmap fb failed: %d\n", errno);
      close(ffd);
      return -errno;
    }

  printf("camview: LCD %dx%d bpp=%d stride=%d\n",
         vinfo.xres, vinfo.yres, pinfo.bpp, pinfo.stride);

  /* Open camera */

  vfd = open("/dev/video", 0);
  if (vfd < 0)
    {
      printf("camview: open /dev/video failed: %d\n", errno);
      munmap(fbmem, pinfo.fblen);
      close(ffd);
      return -errno;
    }

  /* Set camera format: QVGA RGB565 */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width       = CAM_WIDTH;
  fmt.fmt.pix.height      = CAM_HEIGHT;
  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;

  ret = ioctl(vfd, VIDIOC_S_FMT, (uintptr_t)&fmt);
  if (ret < 0)
    {
      printf("camview: VIDIOC_S_FMT failed: %d\n", errno);
      goto errout;
    }

  /* Request buffers */

  memset(&req, 0, sizeof(req));
  req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;
  req.count  = CAMVIEW_BUFNUM;
  req.mode   = V4L2_BUF_MODE_RING;

  ret = ioctl(vfd, VIDIOC_REQBUFS, (uintptr_t)&req);
  if (ret < 0)
    {
      printf("camview: VIDIOC_REQBUFS failed: %d\n", errno);
      goto errout;
    }

  /* Allocate and queue buffers */

  for (cnt = 0; cnt < CAMVIEW_BUFNUM; cnt++)
    {
      bufs[cnt].length = CAM_WIDTH * CAM_HEIGHT * 2;
      bufs[cnt].start  = memalign(32, bufs[cnt].length);
      if (!bufs[cnt].start)
        {
          printf("camview: alloc buf %d failed\n", cnt);
          goto errout;
        }

      memset(&vbuf, 0, sizeof(vbuf));
      vbuf.type      = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      vbuf.memory    = V4L2_MEMORY_USERPTR;
      vbuf.index     = cnt;
      vbuf.m.userptr = (uintptr_t)bufs[cnt].start;
      vbuf.length    = bufs[cnt].length;

      ret = ioctl(vfd, VIDIOC_QBUF, (uintptr_t)&vbuf);
      if (ret < 0)
        {
          printf("camview: QBUF %d failed: %d\n", cnt, errno);
          goto errout;
        }
    }

  /* Start streaming */

  {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(vfd, VIDIOC_STREAMON, (uintptr_t)&type);
    if (ret < 0)
      {
        printf("camview: STREAMON failed: %d\n", errno);
        goto errout;
      }
  }

  printf("camview: streaming started, entering display loop\n");

  /* Main display loop */

  while (1)
    {
      FAR uint16_t *src;
      FAR uint16_t *dst;
      int xoff;
      int yoff;
      int y;

      /* Dequeue a captured frame */

      memset(&vbuf, 0, sizeof(vbuf));
      vbuf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      vbuf.memory = V4L2_MEMORY_USERPTR;

      ret = ioctl(vfd, VIDIOC_DQBUF, (uintptr_t)&vbuf);
      if (ret < 0)
        {
          printf("camview: DQBUF failed: %d\n", errno);
          break;
        }

      src = (FAR uint16_t *)vbuf.m.userptr;

      /* Calculate offset to center the 240x240 crop in the 320x240 frame */

      xoff = (CAM_WIDTH - LCD_WIDTH) / 2;   /* (320-240)/2 = 40 */
      yoff = (CAM_HEIGHT - LCD_HEIGHT) / 2; /* (240-240)/2 = 0  */

      /* Copy center region to framebuffer, row by row
       * Camera stride = CAM_WIDTH * 2 bytes
       * LCD stride    = pinfo.stride bytes
       */

      for (y = 0; y < LCD_HEIGHT; y++)
        {
          dst = (FAR uint16_t *)(fbmem + y * pinfo.stride);
          memcpy(dst, src + (yoff + y) * CAM_WIDTH + xoff,
                 LCD_WIDTH * 2);
        }

      /* Re-queue the buffer */

      ret = ioctl(vfd, VIDIOC_QBUF, (uintptr_t)&vbuf);
      if (ret < 0)
        {
          printf("camview: re-QBUF failed: %d\n", errno);
          break;
        }
    }

errout:
  close(vfd);
  munmap(fbmem, pinfo.fblen);
  close(ffd);
  return ret;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int board_camera_initialize(void)

input.old_string:
  sensor = &g_ov2640_sensor;
  ret = capture_register("/dev/video", data, &sensor, 1);
  if (ret < 0)
    {
      printf("board_camera: capture_register failed: %d\n", ret);
      return ret;
    }

  return OK;
}

input.new_string:
  sensor = &g_ov2640_sensor;
  ret = capture_register("/dev/video", data, &sensor, 1);
  if (ret < 0)
    {
      printf("board_camera: capture_register failed: %d\n", ret);
      return ret;
    }

  /* Start background task to display camera on LCD */

  ret = task_create("camview", 100, 4096, camview_task, NULL);
  if (ret < 0)
    {
      printf("board_camera: camview task create failed: %d\n", ret);
      /* Non-fatal: camera is still registered */
    }
  else
    {
      printf("board_camera: camview task started\n");
    }

  return OK;
}

