165	/****************************************************************************
166	 * Private Data — camera display task
167	 ****************************************************************************/
168	
169	/* Camera capture resolution (QVGA) */
170	
171	#define CAM_WIDTH   320
172	#define CAM_HEIGHT  240
173	
174	/* LCD resolution (ST7789 portrait 240x240) */
175	
176	#define LCD_WIDTH   240
177	#define LCD_HEIGHT  240
178	
179	#define CAMVIEW_BUFNUM  3
180	
181	struct camview_buffer
182	{
183	  FAR uint32_t *start;
184	  uint32_t length;
185	};
186	
187	/****************************************************************************
188	 * Name: camview_task
189	 *
190	 * Description:
191	 *   Background task that captures camera frames and displays them on the
192	 *   LCD framebuffer.  Reads RGB565 frames from /dev/video at QVGA
193	 *   resolution, copies the center 240x240 region to /dev/fb0.
194	 *
195	 ****************************************************************************/
196	
197	static int camview_task(int argc, FAR char *argv[])
198	{
199	  int vfd;
200	  int ffd;
201	  int ret;
202	  int cnt;
203	  struct fb_videoinfo_s vinfo;
204	  struct fb_planeinfo_s pinfo;
205	  FAR uint8_t *fbmem;
206	  struct v4l2_format fmt;
207	  struct v4l2_requestbuffers req;
208	  struct v4l2_buffer vbuf;
209	  struct camview_buffer bufs[CAMVIEW_BUFNUM];
210	
211	  /* Give camera hardware a moment to stabilize */
212	
213	  usleep(500000);
214	
215	  /* Open framebuffer */
216	
217	  ffd = open("/dev/fb0", O_RDWR);
218	  if (ffd < 0)
219	    {
220	      printf("camview: open /dev/fb0 failed: %d\n", errno);
221	      return -errno;
222	    }
223	
224	  ret = ioctl(ffd, FBIOGET_VIDEOINFO, (unsigned long)(uintptr_t)&vinfo);
225	  if (ret < 0)
226	    {
227	      printf("camview: FBIOGET_VIDEOINFO failed: %d\n", errno);
228	      close(ffd);
229	      return -errno;
230	    }
231	
232	  ret = ioctl(ffd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo);
233	  if (ret < 0)
234	    {
235	      printf("camview: FBIOGET_PLANEINFO failed: %d\n", errno);
236	      close(ffd);
237	      return -errno;
238	    }
239	
240	  fbmem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
241	               MAP_SHARED | MAP_FILE, ffd, 0);
242	  if (fbmem == MAP_FAILED)
243	    {
244	      printf("camview: mmap fb failed: %d\n", errno);
245	      close(ffd);
246	      return -errno;
247	    }
248	
249	  printf("camview: LCD %dx%d bpp=%d stride=%d\n",
250	         vinfo.xres, vinfo.yres, pinfo.bpp, pinfo.stride);
251	
252	  /* Open camera */
253	
254	  vfd = open("/dev/video", 0);
255	  if (vfd < 0)
256	    {
257	      printf("camview: open /dev/video failed: %d\n", errno);
258	      munmap(fbmem, pinfo.fblen);
259	      close(ffd);
260	      return -errno;
261	    }
262	
263	  /* Set camera format: QVGA RGB565 */
264	
265	  memset(&fmt, 0, sizeof(fmt));
266	  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
267	  fmt.fmt.pix.width       = CAM_WIDTH;
268	  fmt.fmt.pix.height      = CAM_HEIGHT;
269	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
270	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
271	
272	  ret = ioctl(vfd, VIDIOC_S_FMT, (uintptr_t)&fmt);
273	  if (ret < 0)
274	    {
275	      printf("camview: VIDIOC_S_FMT failed: %d\n", errno);
276	      goto errout;
277	    }
278	
279	  /* Request buffers */
280	
281	  memset(&req, 0, sizeof(req));
282	  req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
283	  req.memory = V4L2_MEMORY_USERPTR;
284	  req.count  = CAMVIEW_BUFNUM;
285	  req.mode   = V4L2_BUF_MODE_RING;
286	
287	  ret = ioctl(vfd, VIDIOC_REQBUFS, (uintptr_t)&req);
288	  if (ret < 0)
289	    {
290	      printf("camview: VIDIOC_REQBUFS failed: %d\n", errno);
291	      goto errout;
292	    }
293	
294	  /* Allocate and queue buffers */
295	
296	  for (cnt = 0; cnt < CAMVIEW_BUFNUM; cnt++)
297	    {
298	      bufs[cnt].length = CAM_WIDTH * CAM_HEIGHT * 2;
299	      bufs[cnt].start  = memalign(32, bufs[cnt].length);
300	      if (!bufs[cnt].start)
301	        {
302	          printf("camview: alloc buf %d failed\n", cnt);
303	          goto errout;
304	        }
305	
306	      memset(&vbuf, 0, sizeof(vbuf));
307	      vbuf.type      = V4L2_BUF_TYPE_VIDEO_CAPTURE;
308	      vbuf.memory    = V4L2_MEMORY_USERPTR;
309	      vbuf.index     = cnt;
310	      vbuf.m.userptr = (uintptr_t)bufs[cnt].start;
311	      vbuf.length    = bufs[cnt].length;
312	
313	      ret = ioctl(vfd, VIDIOC_QBUF, (uintptr_t)&vbuf);
314	      if (ret < 0)
315	        {
316	          printf("camview: QBUF %d failed: %d\n", cnt, errno);
317	          goto errout;
318	        }
319	    }
320	
321	  /* Start streaming */
322	
323	  {
324	    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
325	    ret = ioctl(vfd, VIDIOC_STREAMON, (uintptr_t)&type);
326	    if (ret < 0)
327	      {
328	        printf("camview: STREAMON failed: %d\n", errno);
329	        goto errout;
330	      }
331	  }
332	
333	  printf("camview: streaming started, entering display loop\n");
334	
335	  /* Main display loop */
336	
337	  while (1)
338	    {
339	      FAR uint16_t *src;
340	      FAR uint16_t *dst;
341	      int xoff;
342	      int yoff;
343	      int y;
344	
345	      /* Dequeue a captured frame */
346	
347	      memset(&vbuf, 0, sizeof(vbuf));
348	      vbuf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
349	      vbuf.memory = V4L2_MEMORY_USERPTR;
350	
351	      ret = ioctl(vfd, VIDIOC_DQBUF, (uintptr_t)&vbuf);
352	      if (ret < 0)
353	        {
354	          printf("camview: DQBUF failed: %d\n", errno);
355	          break;
356	        }
357	
358	      src = (FAR uint16_t *)vbuf.m.userptr;
359	
360	      /* Calculate offset to center the 240x240 crop in the 320x240 frame */
361	
362	      xoff = (CAM_WIDTH - LCD_WIDTH) / 2;   /* (320-240)/2 = 40 */
363	      yoff = (CAM_HEIGHT - LCD_HEIGHT) / 2; /* (240-240)/2 = 0  */
364	
365	      /* Copy center region to framebuffer, row by row
366	       * Camera stride = CAM_WIDTH * 2 bytes
367	       * LCD stride    = pinfo.stride bytes
368	       */
369	
370	      for (y = 0; y < LCD_HEIGHT; y++)
371	        {
372	          dst = (FAR uint16_t *)(fbmem + y * pinfo.stride);
373	          memcpy(dst, src + (yoff + y) * CAM_WIDTH + xoff,
374	                 LCD_WIDTH * 2);
375	        }
376	
377	      /* Re-queue the buffer */
378	
379	      ret = ioctl(vfd, VIDIOC_QBUF, (uintptr_t)&vbuf);
380	      if (ret < 0)
381	        {
382	          printf("camview: re-QBUF failed: %d\n", errno);
383	          break;
384	        }
385	    }
386	
387	errout:
388	  close(vfd);
389	  munmap(fbmem, pinfo.fblen);
390	  close(ffd);
391	  return ret;
392	}
