150	
151	  memset(&req, 0, sizeof(req));
152	  req.count = BUF_COUNT;
153	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
154	  req.memory = V4L2_MEMORY_MMAP;
